import re

def cache_namespace(name):
    if type(name) is not str:
        raise TypeError("name must be a string")
    if not re.fullmatch(r"[a-z0-9](?:[a-z0-9-]{0,30}[a-z0-9])?", name):
        raise ValueError("invalid namespace")
    return f"tenant:{name}"

